@Test public void resolvesRelativeLinks() {
    String html = "<a href='/foo'>Link</a><img src='/bar'>";
    String clean = Jsoup.clean(html, "http://example.com/", Safelist.basicWithImages());
    assertEquals("<a href=\"http://example.com/foo\">Link</a><img src=\"http://example.com/bar\">", clean);
}

@Test void cleanDoesNotModifyInputDocumentWhenResolvingRelativeLinks() {
    String html = "<a href='/foo'>Link</a>";
    Cleaner cleaner = new Cleaner(Safelist.basic());
    Document dirty = Jsoup.parseBodyFragment(html, "http://example.com/");
    Document clean = cleaner.clean(dirty);

    assertEquals("<a href=\"http://example.com/foo\">Link</a>", clean.body().html());
    assertEquals("/foo", dirty.expectFirst("a").attr("href"));
}

@Test void isValidDoesNotModifyInputDocumentWhenResolvingRelativeLinks() {
    String html = "<a href='/foo'>Link</a>";
    Cleaner cleaner = new Cleaner(Safelist.basic());
    Document dirty = Jsoup.parseBodyFragment(html, "http://example.com/");

    assertTrue(cleaner.isValid(dirty));
    assertEquals("<a href=\"http://example.com/foo\">Link</a>",
        cleaner.clean(Jsoup.parseBodyFragment(html, "http://example.com/")).body().html());
    assertEquals("/foo", dirty.expectFirst("a").attr("href"));
}

@Test void allPseudoTagProtocolsNormalizeRelativeLinks() {
    Safelist safelist = new Safelist()
        .addTags("a")
        .addAttributes(":all", "href")
        .addProtocols(":all", "href", "http", "https");
    Document dirty = Jsoup.parseBodyFragment("<a href='/foo'>Link</a>", "http://example.com/");

    assertEquals("<a href=\"http://example.com/foo\">Link</a>", new Cleaner(safelist).clean(dirty).body().html());
}

@Test void tagSpecificAttributesDoNotInheritAllPseudoTagProtocols() {
    Safelist safelist = new Safelist()
        .addTags("a")
        .addAttributes("a", "href")
        .addAttributes(":all", "href")
        .addProtocols(":all", "href", "http", "https");
    Document dirty = Jsoup.parseBodyFragment("<a href='/foo'>Link</a>", "http://example.com/");

    assertEquals("<a href=\"/foo\">Link</a>", new Cleaner(safelist).clean(dirty).body().html());
}

@Test public void preservesRelativeLinksIfConfigured() {
    String html = "<a href='/foo'>Link</a><img src='/bar'> <img src='javascript:alert()'>";
    String clean = Jsoup.clean(html, "http://example.com/", Safelist.basicWithImages().preserveRelativeLinks(true));
    assertEquals("<a href=\"/foo\">Link</a><img src=\"/bar\"> <img>", clean);
}

@Test void dropsHostlessUrls() {
    // http(s) URLs need a host after resolution. A one-slash URL resolves against the base when its scheme matches,
    // but remains hostless when its scheme differs; preserved links retain their source spelling after validation
    String html = "<a href='https:/foo/bar'>Cross scheme</a>"
        + "<a href='https://'>Empty host</a>"
        + "<a href='https://?query'>Query without host</a>";

    String clean = Jsoup.clean(html, "http://example.com/a/b", Safelist.basic());

    assertEquals("<a rel=\"nofollow\">Cross scheme</a>"
        + "<a rel=\"nofollow\">Empty host</a>"
        + "<a rel=\"nofollow\">Query without host</a>", clean);
}

@Test void resolvesSameSchemeUrl() {
    String clean = Jsoup.clean("<a href='https:/foo/bar'>Link</a>", "https://example.com/a/b", Safelist.basic());

    assertEquals("<a href=\"https://example.com/foo/bar\">Link</a>", clean);
}

@Test void checksPreservedLinks() {
    Safelist safelist = Safelist.basic().preserveRelativeLinks(true);

    Document httpBase = Jsoup.parseBodyFragment("<a href='https:/foo/bar'>Link</a>", "http://example.com/a/b");
    Cleaner cleaner = new Cleaner(safelist);
    assertFalse(cleaner.isValid(httpBase));
    assertEquals("<a rel=\"nofollow\">Link</a>", cleaner.clean(httpBase).body().html());

    String httpsOutput = Jsoup.clean("<a href='https:/foo/bar'>Link</a>", "https://example.com/a/b", safelist);
    assertEquals("<a href=\"https:/foo/bar\">Link</a>", httpsOutput);
}

@Test public void dropsUnresolvableRelativeLinks() { // when not preserving
    String html = "<a href='/foo'>Link</a>";
    String clean = Jsoup.clean(html, Safelist.basic());
    assertEquals("<a rel=\"nofollow\">Link</a>", clean);
}

@Test void dropsJavascriptWhenRelativeLinks() {
    String html ="<a href='javascript:alert()'>One</a>";
    Safelist safelist = Safelist.basic().preserveRelativeLinks(true);
    assertEquals("<a rel=\"nofollow\">One</a>", Jsoup.clean(html, safelist));
    assertFalse(Jsoup.isValid(html, safelist));
}

@Test void dropsConcealedJavascriptProtocolWhenRelativesLinksEnabled() {
    Safelist safelist = Safelist.basic().preserveRelativeLinks(true);
    String html = "<a href=\"&#0013;ja&Tab;va&Tab;script&#0010;:alert(1)\">Link</a>";
    String clean = Jsoup.clean(html, "https://", safelist);
    assertEquals("<a rel=\"nofollow\">Link</a>", clean);
    assertFalse(Jsoup.isValid(html, safelist));

    String colon = "<a href=\"ja&Tab;va&Tab;script&colon;alert(1)\">Link</a>";
    String cleanColon = Jsoup.clean(colon, "https://", safelist);
    assertEquals("<a rel=\"nofollow\">Link</a>", cleanColon);
    assertFalse(Jsoup.isValid(colon, safelist));
}

@Test void dropsConcealedJavascriptProtocolWhenRelativesLinksDisabled() {
    Safelist safelist = Safelist.basic().preserveRelativeLinks(false);
    String html = "<a href=\"ja&Tab;vas&#0013;cript:alert(1)\">Link</a>";
    String clean = Jsoup.clean(html, "https://", safelist);
    assertEquals("<a rel=\"nofollow\">Link</a>", clean);
    assertFalse(Jsoup.isValid(html, safelist));
}

