    private static class ElementMeta {
        Element el;
        int numAttribsDiscarded;

        ElementMeta(Element el, int numAttribsDiscarded) {
            this.el = el;
            this.numAttribsDiscarded = numAttribsDiscarded;
        }
    }

    // The srcset attribute name, for which candidates are parsed and protocol-checked independently.
    private static final String SrcSetKey = "srcset";

    /**
     Clean an {@code srcset} attribute value: split it into image candidates, validate each candidate's URL against
     the safelist rules of the containing tag, and serialize the surviving candidates in a stable, idempotent form.
     @param sourceEl the owning element (supplies the base URI for relative/protocol resolution)
     @param sourceTag the owning tag's name
     @param srcset the raw attribute value
     @return the normalized value, or {@code null} if the input was blank or no candidate survived (remove the attr)
     */
    private String cleanSrcSet(Element sourceEl, String sourceTag, String srcset) {
        String[] candidates = splitSrcSetCandidates(srcset);
        StringBuilder out = null;

        for (String candidate : candidates) {
            String normalized = normalizeSrcSetCandidate(sourceEl, sourceTag, candidate);
            if (normalized != null) {
                if (out == null)
                    out = new StringBuilder();
                else
                    out.append(", ");
                out.append(normalized);
            }
        }
        return out == null ? null : out.toString();
    }

    /**
     Split a raw srcset value into raw candidate substrings (trimmed), following the srcset comma rules:
     <ul>
       <li>a comma directly followed by a non-whitespace character is part of the URL (e.g. {@code data:...png;base64,AAAA});</li>
       <li>any other comma separates candidates (whitespace around it is insignificant);</li>
       <li>consecutive separators produce empty candidates, which are returned as such and later dropped.</li>
     </ul>
     */
    private static String[] splitSrcSetCandidates(String srcset) {
        List<String> candidates = new ArrayList<>();
        int len = srcset.length();
        int start = 0;

        for (int i = 0; i < len; i++) {
            char c = srcset.charAt(i);
            if (c == ',') {
                if (i + 1 < len && !isAsciiWhitespace(srcset.charAt(i + 1))) {
                    // comma embedded in the URL (the next character belongs to the same run), e.g. data URIs
                    continue;
                }
                candidates.add(srcset.substring(start, i).trim());
                start = i + 1;
            }
        }
        candidates.add(srcset.substring(start).trim());
        return candidates.toArray(new String[0]);
    }

    /**
     Validate and normalize one srcset candidate. A candidate is an optional descriptor separated from the URL by at
     least one ASCII whitespace character. Surviving candidates are serialized as {@code url} or {@code url descriptor}.
     @return the normalized candidate, or {@code null} if it is missing, blank, or syntactically/protocol-invalid
     */
    private String normalizeSrcSetCandidate(Element sourceEl, String sourceTag, String candidate) {
        if (candidate.isEmpty())
            return null; // empty (e.g. consecutive commas) or whitespace-only candidate

        // split into at most two whitespace-separated tokens: URL and optional descriptor
        int split = -1;
        int len = candidate.length();
        for (int i = 0; i < len; i++) {
            if (isAsciiWhitespace(candidate.charAt(i))) {
                split = i;
                break;
            }
        }

        final String url;
        final String descriptor;
        if (split == -1) {
            url = candidate;
            descriptor = null;
        } else {
            url = candidate.substring(0, split);
            // skip the run of whitespace; whatever remains must be exactly one descriptor token
            int descStart = split;
            while (descStart < len && isAsciiWhitespace(candidate.charAt(descStart)))
                descStart++;
            String rest = candidate.substring(descStart);
            if (rest.isEmpty() || containsAsciiWhitespace(rest))
                return null; // trailing whitespace with no descriptor, or multiple descriptor tokens
            descriptor = rest;
        }

        if (url.isEmpty() || (descriptor != null && !isValidSrcSetDescriptor(descriptor)))
            return null;

        if (!safelist.isSafeAttributeValue(sourceTag, sourceEl, SrcSetKey, url))
            return null; // fails this tag's protocol rules, or relative links are not preserved

        return descriptor == null ? url : url + ' ' + descriptor;
    }

    /**
     Validate an srcset descriptor: a positive integer width ({@code 123w}) or a positive number density
     ({@code 2x}). A density number is plain digits or digits-dot-digits; signs, exponents, missing fraction
     digits, and zero values are rejected.
     */
    private static boolean isValidSrcSetDescriptor(String descriptor) {
        int len = descriptor.length();
        if (len < 2)
            return false;
        char suffix = descriptor.charAt(len - 1);

        if (suffix == 'w')
            return isPositiveInteger(descriptor, 0, len - 1);
        if (suffix == 'x')
            return isPositiveNumber(descriptor, 0, len - 1);
        return false; // unknown descriptor
    }

    /** A positive integer: one or more ASCII digits with a value greater than zero. */
    private static boolean isPositiveInteger(String s, int from, int to) {
        if (from >= to)
            return false;
        boolean nonZero = false;
        for (int i = from; i < to; i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9')
                return false;
            if (c != '0')
                nonZero = true;
        }
        return nonZero;
    }

    /**
     A positive number in plain-digit form ({@code 2}, {@code 1.5}) or digits-dot-digits ({@code 2.0}); no sign,
     exponent, or dangling decimal point. Zero values are rejected.
     */
    private static boolean isPositiveNumber(String s, int from, int to) {
        if (from >= to)
            return false;
        int dot = -1;
        for (int i = from; i < to; i++) {
            char c = s.charAt(i);
            if (c == '.') {
                if (dot != -1)
                    return false; // more than one dot
                dot = i;
            } else if (c < '0' || c > '9') {
                return false; // sign, exponent, or any other character
            }
        }
        if (dot != -1 && (dot == from || dot == to - 1))
            return false; // dot must have digits on both sides
