package org.jsoup.safety;

import org.jsoup.Jsoup;

public class ScratchSrcSet {
    public static void main(String[] args) {
        Safelist sl = Safelist.basicWithImages()
            .addAttributes("img", "srcset")
            .addProtocols("img", "srcset", "http", "https", "data")
            .preserveRelativeLinks(true);

        String[] inputs = {
            "a.jpg 1x,b.jpg 2x",
            "a.jpg,2x",
            "a.jpg  1x  2x",
            "data:image/png;base64,AAAA 2x",
            "  a.jpg\t1x  ,  b.jpg\n2x  ",
            "a.jpg,,,,",
            "http://example.com/a,b;c.jpg 1x",
            "a.jpg 1e0x",
            "a.jpg .x",
            "x",
            "a.jpg 1w 2w, b.jpg",
            "http://例え.jp/a.jpg 1x",
        };
        for (String in : inputs) {
            String out = Jsoup.clean("<img srcset=\"" + in + "\">", sl);
            String out2 = Jsoup.clean(out, sl);
            System.out.println("IN : " + in.replace("\n", "\\n").replace("\t", "\\t"));
            System.out.println("OUT: " + out);
            System.out.println("IDEM: " + out.equals(out2));
            System.out.println("VALID: " + Jsoup.isValid("<img srcset=\"" + in + "\">", sl));
            System.out.println();
        }
    }
}

