 */
boolean isAttributeAllowed(String tagName, String attributeKey) {
    TagName tag = TagName.valueOf(tagName);
    AttributeKey key = AttributeKey.valueOf(attributeKey);

    Set<AttributeKey> okSet = attributes.get(tag);
